import { NextRequest, NextResponse } from 'next/server';
import { appendSubscriber } from '@/lib/google-sheets';
import { securityCheck, checkFormSecurity, createRateLimitHeaders } from '@/lib/security';
import { getClientIP } from '@/lib/security/bot-detection';
import { trackRequest } from '@/lib/security/anomaly-detection';
import { logFormSubmission } from '@/lib/security/audit-log';

export async function POST(request: NextRequest) {
  const ip = getClientIP(request);
  const userAgent = request.headers.get('user-agent') || '';
  const path = request.nextUrl.pathname;

  try {
    // Security check
    const securityResult = await securityCheck(request);

    if (!securityResult.allowed) {
      if (securityResult.challenge === 'block') {
        return NextResponse.json(
          { error: 'Forbidden', message: securityResult.reason },
          { status: 403 }
        );
      }
      return NextResponse.json(
        { error: 'Verification Required', message: securityResult.reason, requiresCaptcha: true },
        { status: 429 }
      );
    }

    const body = await request.json();
    const { email } = body;

    // Validate email format
    if (!email || !email.includes('@')) {
      await trackRequest(ip, path, 'POST', 400, userAgent);
      return NextResponse.json(
        { error: 'Invalid email address' },
        { status: 400 }
      );
    }

    // Additional rate limit for subscriptions
    const submitKey = `subscribe:${ip}`;
    const { checkRateLimit } = await import('@/lib/security/rate-limiter');
    const { RATE_LIMITS } = await import('@/lib/security/rate-limit-config');
    const rateLimit = await checkRateLimit(
      submitKey,
      RATE_LIMITS.API.subscribe.requests,
      RATE_LIMITS.API.subscribe.windowSeconds
    );

    if (!rateLimit.allowed) {
      return NextResponse.json(
        { error: 'Too many subscription attempts', message: 'Please try again later' },
        { status: 429 }
      );
    }

    try {
      if (process.env.GOOGLE_SERVICE_ACCOUNT_JSON) {
        await appendSubscriber(email);
      } else {
        console.warn('GOOGLE_SERVICE_ACCOUNT_JSON not set, skipping Google Sheets append.');
      }

      console.log(`[NEWSLETTER LEAD] New subscriber: ${email} at ${new Date().toISOString()}`);

      await trackRequest(ip, path, 'POST', 200, userAgent);
      await logFormSubmission(ip, path, 'newsletter_subscription', false, userAgent);

      return NextResponse.json(
        { message: 'Subscribed successfully' },
        { 
          status: 200,
          headers: createRateLimitHeaders(rateLimit.remaining, rateLimit.resetTime),
        }
      );
    } catch (error) {
      console.error('Newsletter subscription error:', error);
      await trackRequest(ip, path, 'POST', 500, userAgent);
      return NextResponse.json(
        { error: 'Internal server error' },
        { status: 500 }
      );
    }
  } catch (error) {
    console.error('Request processing error:', error);
    await trackRequest(ip, path, 'POST', 400, userAgent);
    return NextResponse.json(
      { error: 'Bad Request' },
      { status: 400 }
    );
  }
}

'use client';

import { useState, useEffect } from 'react';
import { X, Mail, CheckCircle } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { sendGAEvent } from '@/lib/analytics';

export default function ExitIntentPopup() {
  const [isVisible, setIsVisible] = useState(false);
  const [email, setEmail] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isClient, setIsClient] = useState(false);
  const t = useTranslations('NewsletterPopup');

  useEffect(() => {
    setIsClient(true);
  }, []);

  useEffect(() => {
    if (!isClient) return;

    const closedAt = localStorage.getItem('exit_intent_popup_closed');
    const subscribed = localStorage.getItem('newsletter_subscribed');

    if (subscribed) {
      return;
    }

    if (closedAt) {
      const closedDate = new Date(parseInt(closedAt, 10));
      const now = new Date();
      const diffTime = Math.abs(now.getTime() - closedDate.getTime());

      if (diffTime < 7 * 24 * 60 * 60 * 1000) {
        return;
      }
    }

    const handleMouseLeave = (e: MouseEvent) => {
      if (e.clientY <= 0) {
        // Double check subscription status before showing
        if (localStorage.getItem('newsletter_subscribed')) {
          return;
        }
        setIsVisible(true);
        window.dispatchEvent(new CustomEvent('exit-intent-triggered'));
      }
    };

    document.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      document.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, [isClient]);

  const handleClose = () => {
    setIsVisible(false);
    localStorage.setItem('exit_intent_popup_closed', Date.now().toString());
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/subscribe', {
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }) 
      });

      if (!response.ok) {
        throw new Error('Failed to subscribe');
      }

      setSubmitted(true);
      sendGAEvent('sign_up', { method: 'exit_intent_popup' });
      localStorage.setItem('newsletter_subscribed', 'true');

      // Auto-close after success message
      setTimeout(() => {
        setIsVisible(false);
      }, 3000);
    } catch (err) {
      console.error('Failed to subscribe', err);
      setError(t('error'));
    } finally {
      setLoading(false);
    }
  };

  if (!isClient || !isVisible) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-in fade-in duration-300">
      <div className="relative w-full max-w-md overflow-hidden rounded-lg border border-gray-200 bg-white p-6 shadow-2xl dark:border-gray-800 dark:bg-gray-900 animate-in zoom-in-95 duration-300">

        {/* Close Button */}
        <button
          onClick={handleClose}
          className="absolute right-4 top-4 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
          aria-label="Close"
        >
          <X className="h-5 w-5" />
        </button>

        {submitted ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <div className="mb-4 rounded-full bg-green-100 p-4 dark:bg-green-900/30">
              <CheckCircle className="h-10 w-10 text-green-600 dark:text-green-400" />
            </div>
            <h3 className="text-xl font-bold text-gray-900 dark:text-white">
              {t('successTitle')}
            </h3>
            <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
              {t('successSubtitle')}
            </p>
          </div>
        ) : (
          <>
            <div className="mb-6 flex flex-col items-center text-center">
              <div className="mb-4 rounded-full bg-blue-100 p-3 dark:bg-blue-900/30">
                <Mail className="h-8 w-8 text-blue-600 dark:text-blue-400" />
              </div>
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                {t('title')}
              </h3>
              <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                {t('subtitle')}
              </p>
            </div>

            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
              <div className="flex flex-col gap-1">
                <input
                  type="email"
                  placeholder={t('placeholder')}
                  className={`w-full rounded-md border px-4 py-3 text-base placeholder:text-gray-400 focus:outline-none focus:ring-1 ${
                    error
                      ? 'border-red-500 focus:border-red-500 focus:ring-red-500'
                      : 'border-gray-300 focus:border-blue-500 focus:ring-blue-500 dark:border-gray-700 dark:focus:border-blue-400'
                  } dark:bg-gray-800 dark:text-white`}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  disabled={loading}
                />
                {error && <p className="text-xs text-red-500">{error}</p>}
              </div>
              <button
                type="submit"
                disabled={loading}
                className="w-full rounded-md bg-blue-600 px-4 py-3 text-base font-semibold text-white shadow-sm hover:bg-blue-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-600 dark:bg-blue-500 dark:hover:bg-blue-400 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? t('submitting') : t('button')}
              </button>
              <p className="text-center text-xs text-gray-400 dark:text-gray-500">
                {t('spam')}
              </p>
            </form>
          </>
        )}
      </div>
    </div>
  );
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type GTag = (...args: any[]) => void;

declare global {
  interface Window {
    gtag?: GTag;
  }
}

export const sendGAEvent = (eventName: string, params?: Record<string, string | number | boolean | null | undefined>) => {
  if (typeof window !== "undefined" && window.gtag) {
    window.gtag("event", eventName, params);
  }
};

